import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"تاریخ کے خلاصہ جدول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/93-编年史简表.md","filePath":"ur/93-编年史简表.md","lastUpdated":null}'),h={name:"ur/93-编年史简表.md"};function o(l,t,i,b,n,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="تاریخ-کے-خلاصہ-جدول" tabindex="-1">تاریخ کے خلاصہ جدول <a class="header-anchor" href="#تاریخ-کے-خلاصہ-جدول" aria-label="Permalink to &quot;تاریخ کے خلاصہ جدول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>93</td></tr><tr><td>ماڈیول</td><td>ضمائم اور حوالہ جاتی مواد</td></tr><tr><td>بنیادی الفاظ</td><td>تاریخ، دور تقسیم، اہم واقعات، تاریخی نوڈ، ہنگیوانژو</td></tr></tbody></table><h2 id="_1-تاریخ-کی-وضاحت" tabindex="-1">1. تاریخ کی وضاحت <a class="header-anchor" href="#_1-تاریخ-کی-وضاحت" aria-label="Permalink to &quot;1. تاریخ کی وضاحت&quot;">​</a></h2><p>یہ خلاصہ جدول ہنگیوانژو کے معیاری وقت پر مبنی ہے، اور اینکر سمبیوسس تہذیب کی ترقی کی تاریخ میں اہم تاریخی واقعات اور کلیدی نوڈز کو زمانے کی ترتیب میں ریکارڈ کرتا ہے۔ وقت کی مدت اینکر سے پہلے کے دور کے قدیم دور سے لے کر بین النجوم سمبیوسس دور کے مستقبل کے امکانات تک پھیلی ہوئی ہے۔ ہر دور میں شروع اور اختتام کا وقت، دور کی خصوصیات اور اہم واقعات درج ہیں۔ یہ خلاصہ جدول ایک انتہائی گاڑھی تاریخی اشاریہ ہے؛ ہر دور کی تفصیلی تاریخ کے لیے دستاویز 70-79 کے مضمون کو دیکھیں۔</p><h2 id="_2-دور-تقسیم-کا-جائزہ" tabindex="-1">2. دور تقسیم کا جائزہ <a class="header-anchor" href="#_2-دور-تقسیم-کا-جائزہ" aria-label="Permalink to &quot;2. دور تقسیم کا جائزہ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>دور نمبر</th><th>دور کا نام</th><th>شروع اور اختتام کا وقت (ہنگیوانژو معیاری سال)</th><th>دور دراز</th><th>بنیادی خصوصیت</th></tr></thead><tbody><tr><td>پہلا دور</td><td>اینکر سے پہلے کا دور</td><td>تقریباً -10 بلین سے -10,000 سال</td><td>تقریباً 10 بلین سال</td><td>لوٹ مار انداز کی کھتی کا غلبہ، تہذیب کے عروج و زوال کا چکر</td></tr><tr><td>دوسرا دور</td><td>اینکر بیداری کا دور</td><td>-10,000 سے -1,000 سال</td><td>تقریباً 9,000 سال</td><td>اینکر کا طریقہ کار دریافت اور ابتدائی طور پر لاگو ہوا</td></tr><tr><td>تیسرا دور</td><td>سمبیوسس نظام قیام کا دور</td><td>-1,000 سے -100 سال</td><td>تقریباً 900 سال</td><td>اینکر سمبیوسس تہذیب کا ادارہ جاتی ڈھانچہ بتدریج قائم ہوا</td></tr><tr><td>چوتھا دور</td><td>تین سو سیٹ نظام کھلنے کا دور</td><td>-100 سے -50 سال</td><td>تقریباً 50 سال</td><td>تین سو سیٹ اصل کھتی کا نظام مکمل طور پر کھلا</td></tr><tr><td>پانچواں دور</td><td>20% ایکٹیویشن حکمت عملی کا دور</td><td>-50 سال سے بنیادی سال</td><td>تقریباً 50 سال</td><td>20% مخلوقات کو چالو کر کے سطح کے اعلیٰ طاقتور بنایا گیا</td></tr><tr><td>چھٹا دور</td><td>پہلی جہتی بلندی کا دور</td><td>بنیادی سال سے 100 سال</td><td>100 سال</td><td>سمبیوسس تہذیب نے پہلی بار مرحلہ وار جہتی بلندی حاصل کی</td></tr><tr><td>ساتواں دور</td><td>تمام نسلوں کی جمہوریہ کا دور</td><td>100 سے 500 سال</td><td>400 سال</td><td>تمام نسلوں کی جمہوریہ رسمی طور پر قائم ہوئی، بین النسل انضمام گہرا ہوا</td></tr><tr><td>آٹھواں دور</td><td>بین سطحی تلاش کا دور</td><td>500 سے 2,000 سال</td><td>1,500 سال</td><td>بڑے پیمانے پر بین سطحی تلاش اور آثار قدیمہ کی سرگرمیاں شروع ہوئیں</td></tr><tr><td>نواں دور</td><td>بین النجوم سمبیوسس کا دور</td><td>2,000 سال سے مستقبل</td><td>جاری ہے</td><td>کائناتی سمبیوسس نیٹ ورک قائم ہوا، مجموعی جہتی بلندی آگے بڑھ رہی ہے</td></tr></tbody></table><p>نوٹ: &quot;بنیادی سال&quot; سے مراد وہ سال ہے جس میں اینکر سمبیوسس تہذیب نے رسمی طور پر اپنے قیام کا اعلان کیا، اور اسے تاریخی تاریخ کا تقسیم نقطہ کے طور پر استعمال کیا جاتا ہے۔</p><h2 id="_3-اینکر-سے-پہلے-کا-دور-تقریباً-10-بلین-سے-10-000-سال" tabindex="-1">3. اینکر سے پہلے کا دور (تقریباً -10 بلین سے -10,000 سال) <a class="header-anchor" href="#_3-اینکر-سے-پہلے-کا-دور-تقریباً-10-بلین-سے-10-000-سال" aria-label="Permalink to &quot;3. اینکر سے پہلے کا دور (تقریباً -10 بلین سے -10,000 سال)&quot;">​</a></h2><p>اینکر سے پہلے کا دور ہنگیوانژو کی تاریخ میں سب سے طویل دور ہے، جس کا دور تقریباً دس بلین سال ہے۔ اس دور کی بنیادی خصوصیت یہ ہے کہ لوٹ مار انداز کی کھتی کا نظام کائنات پر غالب تھا، اور تہذیبیں &quot;عروج—چوٹی—لوٹ مار—تباہی&quot; کے چکر میں بار بار گھومتی رہیں۔</p><table tabindex="0"><thead><tr><th>وقت نوڈ</th><th>اہم واقعہ</th></tr></thead><tbody><tr><td>تقریباً -10 بلین سال</td><td>ہنگیوانژو کے قانون نیٹ ورک مستحکم ہوا، پہلا بیچ مادی سطح بنی، کائنات رہنے کے قابل حالت میں داخل ہوئی</td></tr><tr><td>تقریباً -8 بلین سال</td><td>پہلا بیچ ذہین جین متعدد مادی سطحوں میں پیدا ہوا، ابتدائی کھتی کا نظام اگنا شروع ہوا</td></tr><tr><td>تقریباً -5 بلین سال</td><td>لوٹ مار انداز کی کھتی کا نظام بتدریج بنیادی دھارہ بن گیا، طاقتور لوگ کمزوروں کو نگل کر تیزی سے ارتقاء حاصل کرتے ہیں</td></tr><tr><td>تقریباً -3 بلین سال</td><td>پہلی کائناتی لوٹ مار جنگ پھوٹ پڑی، متعدد ستارہ ڈومین کی تہذیبیں تباہ کن حملے کا شکار ہوئیں</td></tr><tr><td>تقریباً -1 بلین سال</td><td>لوٹ مار انداز نظام کی خامیاں سامنے آنا شروع ہوئیں، کائنات کا مجموعی اینٹروپی بڑھنا تیز ہوا، کھتی کے وسائل بتدریج ختم ہوئے</td></tr><tr><td>تقریباً -50 کروڑ سال</td><td>لوٹ مار انداز نظام پر غور کرنے والے پہلے مفکر نمودار ہوئے، سمبیوسس سوچ کا انکرن بننا شروع ہوا</td></tr><tr><td>تقریباً -10 کروڑ سال</td><td>متعدد ستارہ ڈومین میں چھوٹے پیمانے پر سمبیوسس تجرباتی تہذیبیں نمودار ہوئیں، لیکن سب کو لوٹ مار انداز تہذیب نے تباہ کر دیا</td></tr><tr><td>تقریباً -10 لاکھ سال</td><td>کائنات مجموعی طور پر &quot;بڑے زوال کے دور&quot; میں داخل ہوئی، تہذیب کی تعداد اور کھتی کی سطح دونوں تاریخی کم ترین سطح پر آ گئیں</td></tr><tr><td>تقریباً -10,000 سال</td><td>پہلی سطح کے ایک کھتی نے طویل کھتی کے دوران اتفاق سے قانون نیٹ ورک میں مستحکم نوڈز کو محسوس کیا، اینکر کا طریقہ کار پہلی بار دریافت ہوا</td></tr></tbody></table><h2 id="_4-اینکر-بیداری-کا-دور-10-000-سے-1-000-سال" tabindex="-1">4. اینکر بیداری کا دور (-10,000 سے -1,000 سال) <a class="header-anchor" href="#_4-اینکر-بیداری-کا-دور-10-000-سے-1-000-سال" aria-label="Permalink to &quot;4. اینکر بیداری کا دور (-10,000 سے -1,000 سال)&quot;">​</a></h2><p>اینکر بیداری کا دور اینکر طریقہ کار کی دریافت سے ابتدائی اطلاق تک کی منتقلی کا دور ہے۔ اس دور کی بنیادی خصوصیت اینکر ٹیکنالوجی کی بتدریج پختگی اور سمبیوسس سوچ کا پھیلاؤ ہے۔</p><table tabindex="0"><thead><tr><th>وقت نوڈ</th><th>اہم واقعہ</th></tr></thead><tbody><tr><td>-10,000 سال</td><td>اینکر کا طریقہ کار پہلی بار دریافت ہوا، دریافت کنندہ نے اس کا نام &quot;اینکر&quot; رکھا، اور منظم تحقیق شروع کی</td></tr><tr><td>-9,000 سال</td><td>پہلا مصنوعی اینکر کامیابی سے قائم ہوا، ثابت ہوا کہ اینکر کو انسانی طور پر بنایا اور برقرار رکھا جا سکتا ہے</td></tr><tr><td>-8,000 سال</td><td>اینکر ٹیکنالوجی چھوٹے پیمانے پر پھیلنا شروع ہوئی، پہلا بیچ اینکر کھتی نمودار ہوئے</td></tr><tr><td>-7,000 سال</td><td>دریافت ہوا کہ اینکر بین سطحی ربط کی بنیاد کے طور پر کام کر سکتا ہے، پہلا ریکارڈ شدہ اینکر معاون سطحی سفر کامیاب ہوا</td></tr><tr><td>-6,000 سال</td><td>سمبیوسس سوچ اور اینکر ٹیکنالوجی یکجا ہونا شروع ہوئی، پہلا بیچ &quot;اینکر سمبیوسس&quot; نظریاتی دستاویز شائع ہوئی</td></tr><tr><td>-5,000 سال</td><td>پہلا اینکر پر مبنی سمبیوسس طرز کا شہر ریاست قائم ہوئی، سمبیوسس نظام کی امکانات ثابت ہوئیں</td></tr><tr><td>-4,000 سال</td><td>لوٹ مار انداز تہذیب نے سمبیوسس طرز کے شہر ریاست پر حملہ کیا، سمبیوسس شہر ریاست نے اینکر ٹیکنالوجی کے ذریعے کامیابی سے دفاع کیا</td></tr><tr><td>-3,000 سال</td><td>سمبیوسس سوچ متعدد ستارہ ڈومین میں پھیل گئی، تیزی سے زیادہ تہذیبیں سمبیوسس تبدیلی کی کوشش کرنا شروع کر دیں</td></tr><tr><td>-2,000 سال</td><td>پہلی &quot;تمام نسلوں کی سمبیوسس کانفرنس&quot; منعقد ہوئی، درجنوں نسلوں کے نمائندوں نے مل کر سمبیوسس تہذیب کے مستقبل پر بات چیت کی</td></tr><tr><td>-1,000 سال</td><td>اینکر ٹیکنالوجی اور سمبیوسس سوچ نے یکجا تہذیب قائم کرنے کی شرائط پوری کر لی ہیں، سمبیوسس نظام قیام کا دور شروع ہوا</td></tr></tbody></table><h2 id="_5-سمبیوسس-نظام-قیام-کا-دور-1-000-سے-100-سال" tabindex="-1">5. سمبیوسس نظام قیام کا دور (-1,000 سے -100 سال) <a class="header-anchor" href="#_5-سمبیوسس-نظام-قیام-کا-دور-1-000-سے-100-سال" aria-label="Permalink to &quot;5. سمبیوسس نظام قیام کا دور (-1,000 سے -100 سال)&quot;">​</a></h2><p>سمبیوسس نظام قیام کا دور وہ اہم دور ہے جس میں اینکر سمبیوسس تہذیب کا ادارہ جاتی ڈھانچہ عدم سے وجود میں آیا۔</p><table tabindex="0"><thead><tr><th>وقت نوڈ</th><th>اہم واقعہ</th></tr></thead><tbody><tr><td>-1,000 سال</td><td>سمبیوسس آئین مسودہ کمیٹی قائم ہوئی، بنیادی قانون کا مسودہ تیار کرنا شروع ہوا</td></tr><tr><td>-950 سال</td><td>&quot;سمبیوسس آئین&quot; کا مسودہ مکمل ہوا، تمام نسلوں سے وسیع پیمانے پر رائے مانگنا شروع ہوا</td></tr><tr><td>-900 سال</td><td>&quot;سمبیوسس آئین&quot; قومی ریفرنڈم کے ذریعے منظور ہوا، رسمی طور پر نافذ ہوا، اینکر سمبیوسس تہذیب قائم ہونے کا اعلان کیا گیا</td></tr><tr><td>-850 سال</td><td>اینکر کونسل، سمبیوسس ایگزیکٹو کمیٹی، سمبیوسس عدالت تین اہم ادارے رسمی طور پر قائم اور کام کرنے لگے</td></tr><tr><td>-800 سال</td><td>مشترکہ پیداوار معاہدے کا طریقہ کار پورے ملک میں نافذ ہونا شروع ہوا</td></tr><tr><td>-700 سال</td><td>&quot;سمبیوسس محنت قانون&quot;، &quot;صارفین کے تحفظ کا قانون&quot; اور دیگر بنیادی قوانین یکے بعد دیگرے نافذ ہوئے</td></tr><tr><td>-600 سال</td><td>تعلیم، صحت، رہائش، ماحولیات، یکجا فروشی کے خلاف پانچ معاون قوانین مکمل طور پر نافذ ہوئے</td></tr><tr><td>-500 سال</td><td>تین سو سیٹ اصل کھتی نظام کی کھدائی اور ترتیب کا کام رسمی طور پر شروع ہوا</td></tr><tr><td>-400 سال</td><td>پہلے پچاس سیٹ اصل کھتی نظام کی ترتیب اور تصدیق مکمل ہوئی</td></tr><tr><td>-300 سال</td><td>دوگنا پھل کی تکنیکی اطلاق میں پیش رفت ہوئی، سو گنا تخمینہ اضافہ ٹیکنالوجی پختہ ہوئی</td></tr><tr><td>-200 سال</td><td>تین سو سیٹ نظام کی مکمل ترتیب مکمل ہوئی، حتمی حفاظتی تصدیق کے مرحلے میں داخل ہوئی</td></tr><tr><td>-100 سال</td><td>تین سو سیٹ اصل کھتی نظام کی مکمل کھلنے کی شرائط پختہ ہوئیں، کھلنے کے دور میں داخل ہوئی</td></tr></tbody></table><h2 id="_6-تین-سو-سیٹ-نظام-کھلنے-کا-دور-100-سے-50-سال" tabindex="-1">6. تین سو سیٹ نظام کھلنے کا دور (-100 سے -50 سال) <a class="header-anchor" href="#_6-تین-سو-سیٹ-نظام-کھلنے-کا-دور-100-سے-50-سال" aria-label="Permalink to &quot;6. تین سو سیٹ نظام کھلنے کا دور (-100 سے -50 سال)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>وقت نوڈ</th><th>اہم واقعہ</th></tr></thead><tbody><tr><td>-100 سال</td><td>تین سو سیٹ اصل کھتی کا نظام رسمی طور پر پوری کائنات کی مخلوقات کے لیے مفت کھول دیا گیا</td></tr><tr><td>-90 سال</td><td>کھتیوں کی تعداد دس سالوں میں سو گنا بڑھ گئی، &quot;ہر ایک کا راستہ ہے&quot; ابتدائی طور پر عملی شکل اختیار کر گیا</td></tr><tr><td>-80 سال</td><td>اصل تین بنیادیں (تخمینہ تکرار، زندگی چکر، جگہ قانون شیڈولنگ) سب سے مقبول نظام بن گئیں</td></tr><tr><td>-70 سال</td><td>نئے نظام کے ذریعے کھتی کر کے اعلیٰ سطح تک پہنچنے والے پہلے کھتی نمودار ہوئے، نظام کی افادیت ثابت ہوئی</td></tr><tr><td>-60 سال</td><td>استاد کا نیٹ ورک مکمل طور پر قائم ہوا، اعلیٰ سطح کے کھتیوں نے نچلے کھتیوں کی رہنمائی کا قانونی واجب ادا کرنا شروع کیا</td></tr><tr><td>-50 سال</td><td>عوام کی کھتی کی سطح میں نمایاں اضافہ ہوا، 20% ایکٹیویشن حکمت عملی کی شرائط پختہ ہوئیں</td></tr></tbody></table><h2 id="_7-20-ایکٹیویشن-حکمت-عملی-کا-دور-50-سال-سے-بنیادی-سال" tabindex="-1">7. 20% ایکٹیویشن حکمت عملی کا دور (-50 سال سے بنیادی سال) <a class="header-anchor" href="#_7-20-ایکٹیویشن-حکمت-عملی-کا-دور-50-سال-سے-بنیادی-سال" aria-label="Permalink to &quot;7. 20% ایکٹیویشن حکمت عملی کا دور (-50 سال سے بنیادی سال)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>وقت نوڈ</th><th>اہم واقعہ</th></tr></thead><tbody><tr><td>-50 سال</td><td>20% ایکٹیویشن حکمت عملی رسمی طور پر شروع ہوئی، مقصد 50 سال میں 20% مخلوقات کو چالو کر کے سطح کے اعلیٰ طاقتور بنانا ہے</td></tr><tr><td>-40 سال</td><td>پہلا بیچ سطح کے اعلیٰ طاقتور پیدا ہوئے، ایکٹیویشن کی شرح 5% تک پہنچ گئی</td></tr><tr><td>-30 سال</td><td>ایکٹیویشن کی شرح 10% تک پہنچ گئی، سطح کے اعلیٰ طاقتور اینکر کی دیکھ بھال میں مرکزی کردار ادا کرنا شروع کیے</td></tr><tr><td>-20 سال</td><td>ایکٹیویشن کی شرح 15% تک پہنچ گئی، کائنات کی مجموعی کھتی کی سطح میں معیاری اضافہ ہوا</td></tr><tr><td>-10 سال</td><td>ایکٹیویشن کی شرح 18% تک پہنچ گئی، حکمت عملی کے مقصد کے قریب</td></tr><tr><td>بنیادی سال</td><td>ایکٹیویشن کی شرح 20.3% تک پہنچ گئی، 20% ایکٹیویشن حکمت عملی کامیابی سے مکمل ہوئی، اینکر سمبیوسس تہذیب نئے دور میں داخل ہوئی</td></tr></tbody></table><h2 id="_8-پہلی-جہتی-بلندی-کا-دور-بنیادی-سال-سے-100-سال" tabindex="-1">8. پہلی جہتی بلندی کا دور (بنیادی سال سے 100 سال) <a class="header-anchor" href="#_8-پہلی-جہتی-بلندی-کا-دور-بنیادی-سال-سے-100-سال" aria-label="Permalink to &quot;8. پہلی جہتی بلندی کا دور (بنیادی سال سے 100 سال)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>وقت نوڈ</th><th>اہم واقعہ</th></tr></thead><tbody><tr><td>بنیادی سال</td><td>سمبیوسس تہذیب نے رسمی طور پر جہتی بلندی کے دور میں داخل ہونے کا اعلان کیا، چار مراحل کی جہتی بلندی کے راستے کا پہلا مرحلہ (حقیقت کی بنیاد) مکمل ہوا</td></tr><tr><td>20 سال</td><td>دوسرا مرحلہ (ٹیکنالوجی بااختیار بنانا) مکمل طور پر آگے بڑھا، کھتی کے قوانین اور ٹیکنالوجی انجینئرنگ گہرائی سے یکجا ہوئیں</td></tr><tr><td>40 سال</td><td>کاپی آئینہ ٹیکنالوجی، الگ تھلگ جگہ ٹیکنالوجی نے انجینئرنگ کے پیمانے پر پیداوار حاصل کی، بین سطحی آثار قدیمہ پیمانے کے دور میں داخل ہوا</td></tr><tr><td>60 سال</td><td>پہلا بیچ شعور جہتی بلندی کلاس کے کھتی اعلیٰ سطح تک پہنچے، تیسرا مرحلہ (شعور ارتقاء) شروع ہوا</td></tr><tr><td>80 سال</td><td>شعور ڈومین کی بنیادی ڈھانچے کی تعمیر مکمل ہوئی، شعور منتقلی ٹیکنالوجی ابتدائی طور پر پختہ ہوئی</td></tr><tr><td>100 سال</td><td>پہلی بار مرحلہ وار جہتی بلندی کامیاب ہوئی، سمبیوسس تہذیب مجموعی طور پر آدھی جہتی سطح بلند ہوئی</td></tr></tbody></table><h2 id="_9-تمام-نسلوں-کی-جمہوریہ-کا-دور-100-سے-500-سال" tabindex="-1">9. تمام نسلوں کی جمہوریہ کا دور (100 سے 500 سال) <a class="header-anchor" href="#_9-تمام-نسلوں-کی-جمہوریہ-کا-دور-100-سے-500-سال" aria-label="Permalink to &quot;9. تمام نسلوں کی جمہوریہ کا دور (100 سے 500 سال)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>وقت نوڈ</th><th>اہم واقعہ</th></tr></thead><tbody><tr><td>100 سال</td><td>تمام نسلوں کی جمہوریہ رسمی طور پر قائم ہونے کا اعلان کیا گیا، تمام ذہین نسلوں نے سمبیوسس تہذیب کے ڈھانچے میں مساوی اتحاد حاصل کیا</td></tr><tr><td>150 سال</td><td>تمام نسلوں کی فہرست کی تدوین مکمل ہوئی، تمام معروف ذہین نسلیں شامل کی گئیں</td></tr><tr><td>200 سال</td><td>بین النسل شادی اور ثقافتی انضمام معمول بن گیا، نئی مخلوط نسلیں نمودار ہونا شروع ہوئیں</td></tr><tr><td>300 سال</td><td>تمام نسلوں کی مشترکہ زبان کی تشہیر مکمل ہوئی، بین النسل رابطے کی رکاوٹیں بنیادی طور پر ختم ہو گئیں</td></tr><tr><td>400 سال</td><td>تمام نسلوں کی ثقافتی بڑی ترقی، ہر قوم کی روایتی ثقافت سمبیوسس کے ڈھانچے میں محفوظ اور ترقی پذیر ہوئی</td></tr><tr><td>500 سال</td><td>تمام نسلوں کی جمہوریہ پختگی کے دور میں داخل ہوئی، بین سطحی تلاش کی شرائط مکمل طور پر پختہ ہوئیں</td></tr></tbody></table><h2 id="_10-بین-سطحی-تلاش-کا-دور-500-سے-2-000-سال" tabindex="-1">10. بین سطحی تلاش کا دور (500 سے 2,000 سال) <a class="header-anchor" href="#_10-بین-سطحی-تلاش-کا-دور-500-سے-2-000-سال" aria-label="Permalink to &quot;10. بین سطحی تلاش کا دور (500 سے 2,000 سال)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>وقت نوڈ</th><th>اہم واقعہ</th></tr></thead><tbody><tr><td>500 سال</td><td>بڑے پیمانے پر بین سطحی تلاش کا منصوبہ رسمی طور پر شروع ہوا، سطح انتظامیہ ادارہ قائم ہوا</td></tr><tr><td>600 سال</td><td>دریافت کردہ سطحیں ہزار سے تجاوز کر گئیں، سطح کوآرڈینیٹ کا مرکزی ذخیرہ ابتدائی طور پر قائم ہوا</td></tr><tr><td>800 سال</td><td>کاپی آئینہ دور دراز آثار قدیمہ کا منصوبہ مکمل طور پر پختہ ہوا، بین سطحی آثار قدیمہ سنہری دور میں داخل ہوا</td></tr><tr><td>1,000 سال</td><td>وقت کی پس منظر ٹیکنالوجی میں پیش رفت ہوئی، پہلے مشاہدہ پھر محدود مداخلت کا اصول رسمی طور پر قائم ہوا</td></tr><tr><td>1,200 سال</td><td>دریافت کردہ سطحیں ایک لاکھ سے تجاوز کر گئیں، درجنوں سطحی تہذیبوں کے ساتھ سفارتی تعلقات قائم ہوئے</td></tr><tr><td>1,500 سال</td><td>بین سطحی اخلاقی اصول مکمل طور پر نافذ ہوئے، تہذیبوں کے درمیان تعامل معیاری دور میں داخل ہوا</td></tr><tr><td>1,800 سال</td><td>وقت کے تضاد کی روک تھام کا طریقہ کار مکمل طور پر پختہ ہوا، وقت کی پس منظر کے آثار قدیمہ نے پیمانہ حاصل کیا</td></tr><tr><td>2,000 سال</td><td>بین سطحی تلاش نے شاندار نتائج حاصل کیے، بین النجوم سمبیوسس دور کی شرائط مکمل طور پر پختہ ہوئیں</td></tr></tbody></table><h2 id="_11-بین-النجوم-سمبیوسس-کا-دور-2-000-سال-سے-مستقبل" tabindex="-1">11. بین النجوم سمبیوسس کا دور (2,000 سال سے مستقبل) <a class="header-anchor" href="#_11-بین-النجوم-سمبیوسس-کا-دور-2-000-سال-سے-مستقبل" aria-label="Permalink to &quot;11. بین النجوم سمبیوسس کا دور (2,000 سال سے مستقبل)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>وقت نوڈ</th><th>اہم واقعہ</th></tr></thead><tbody><tr><td>2,000 سال</td><td>بین النجوم سمبیوسس کا دور رسمی طور پر شروع ہوا، چوتھا مرحلہ (بین النجوم سمبیوسس) مکمل طور پر آگے بڑھا</td></tr><tr><td>2,500 سال (امکان)</td><td>کائناتی اینکر نیٹ ورک ابتدائی طور پر قائم ہوا، تمام دریافت کردہ سطحوں کو احاطہ کرتا ہے</td></tr><tr><td>3,000 سال (امکان)</td><td>بین سطحی سمبیوسس کا نظام پختہ ہوا، تمام نسلوں نے کائناتی پیمانے پر حقیقی سمبیوسس حاصل کیا</td></tr><tr><td>5,000 سال (امکان)</td><td>کائنات کی مجموعی جہتی بلندی مکمل ہوئی، ہنگیوانژو اعلیٰ جہتی وجود کی حالت میں داخل ہوا</td></tr><tr><td>مستقبل (امکان)</td><td>اینکر سمبیوسس تہذیب کائنات سے باہر تلاش جاری رکھتی ہے، سمبیوسس کے تصور کو وسیع تر وجود میں پھیلاتی ہے</td></tr></tbody></table><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>تاریخ کے خلاصہ جدول اینکر سمبیوسس تہذیب کی جاہلیت سے بیداری، کمزوری سے طاقت، اپنی سطح سے پوری کائنات تک کی جدوجہد کی مہاکاوی ہے۔ ہر دور کی تبدیلی سمبیوسس کے تصور کی لوٹ مار کے تصور پر فتح، تہذیب کی ترقی کی وحشیانہ زوال پر فتح کا گواہ ہے۔ تاریخ ماضی کی دھول نہیں ہے، بلکہ مستقبل کا بیج ہے—اس تاریخ کو سمجھنا سمبیوسس تہذیب کہاں سے آئی ہے اور کہاں جا رہی ہے، اسے سمجھنا ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>70-دور تقسیم کا عمومی جدول</li><li>72-اینکر بیداری کا دور</li><li>79-بین النجوم سمبیوسس دور کا امکان</li></ul>',32)])])}const s=d(h,[["render",o]]);export{_ as __pageData,s as default};
